try {
  const response = $input.first().json;
  const records = response.records || response.list || (Array.isArray(response) ? response : []);
  const ref = $('Initialisation Tracker').first().json.mission.body?.ref || $('Initialisation Tracker').first().json.mission.query?.ref || $('Initialisation Tracker').first().json.mission.ref || '';
  const row = records.find(candidate => { const f = candidate.fields || candidate; return (f.Code_Mission || f.Reference_Mission || f.reference_mission) === ref; });
  if (!row) return [{ json: { success: true, found: false, reference: ref } }];
  const f = row.fields || row;
  return [{ json: { success: true, found: true, reference: ref, statut: f.Statut || '', sha256_hash: f.Contrat_Hash_Ref || '', webViewLink: f.webViewLink || '' } }];
} catch (err) { throw new Error(`Mapping statut Tracker impossible: ${err.message}`); }

try {
  const response = $input.first().json;
  const records = response.records || response.list || (Array.isArray(response) ? response : []);
  const mission = $('Initialisation standardisée').first().json.mission.body || $('Initialisation standardisée').first().json.mission;
  const row = records.find(candidate => { const f = candidate.fields || candidate; return (f.Code_Mission || f.Reference_Mission || f.reference_mission) === (mission.reference || mission.reference_mission); });
  if (!row) throw new Error('Mission absente du registre NocoDB.');
  const f = row.fields || row;
  const recordId = row.id || row.id_fields?.Id || f.Id || f.id;
  if (!Number.isSafeInteger(Number(recordId))) throw new Error('ID numérique NocoDB manquant ou invalide.');
  const amountValue = mission.montant ?? mission.amount;
  const amount = Number(amountValue);
  if (amountValue === undefined || !Number.isFinite(amount) || amount < 0) throw new Error('Montant de séquestre manquant ou invalide.');
  const phone = String(mission.telephone || '').replace(/\D/g, '');
  if (!/^\d{8,15}$/.test(phone)) throw new Error('telephone au format chiffres seuls manquant ou invalide.');
  const webViewLink = mission.webViewLink || mission.pdf_url;
  if (!webViewLink) throw new Error('Lien webViewLink du rapport manquant.');
  return [{ json: { ...mission, telephone: phone, record_id: Number(recordId), sha256_hash: mission.sha256_hash || f.Contrat_Hash_Ref || '', patch: { id: Number(recordId), fields: { Statut: 'Livré au client', Contrat_Hash_Ref: mission.sha256_hash || f.Contrat_Hash_Ref || '' } }, escrow: { devise: mission.currency || 'EUR', montant_total: amount, part_cabinet: Math.round(amount * 0.15 * 100) / 100, part_expert: Math.round(amount * 0.85 * 100) / 100, expert_release_at: new Date(Date.now() + 5 * 24 * 60 * 60 * 1000).toISOString() }, webViewLink } }];
} catch (err) { throw new Error(`Mapping délivrance impossible: ${err.message}`); }
